def flatten(d: dict) -> dict:
    result = {}
    for key, value in d.items():
        if isinstance(value, dict):
            nested_result = {f"{key}.{k}": v for k, v in value.items()}
            result.update(nested_result)
        else:
            result[key] = value
    return result
```

