import re

def parse_money(s: str) -> float | None:
    if not s or s.strip() == "":
        return None

    # Strip whitespace, remove leading/trailing spaces
    s = s.strip()

    # Check for common non-numeric strings like "n/a", "-", etc.
    if re.match(r'^[a-zA-Z\-]+$', s):
        return None

    # Remove the dollar sign if present at the start
    if s.startswith('$'):
        s = s[1:]

    # Use regex to extract only digits and one decimal point
    match = re.search(r'(\d+(?:\.\d+)?)', s)
    if not match:
        return None

    try:
        value = float(match.group(1))
        return value
    except ValueError:
        return None
